window.SITE = {"name":"English Country Reading Atlas","tagline":"Read the world, one country at a time.","latest":"france","regions":["Asia","Middle East","Europe"]};
window.COUNTRIES = [{"slug":"nepal","name":"Nepal","region":"Asia","flag":"np","mapId":"524","readOrder":1,"summary":"Mountains, temples, and two major religious traditions shape this Himalayan country.","summaryZh":"高山、寺庙以及两种重要宗教传统共同塑造了这个喜马拉雅国家。","facts":{"Capital":"Kathmandu","Language":"Nepali","Landscape":"Himalayas and valleys","Reading path":"Start"},"articles":[{"id":"1","title":"Nepal – A Country in the Mountains","titleZh":"尼泊尔——山中的国家","level":"A2","summary":"A simple introduction to Nepal’s location, mountains, and religious heritage.","summaryZh":"用简单英文认识尼泊尔的位置、高山与宗教文化。","sections":[{"heading":"Location and Capital","headingZh":"位置与首都","en":"Nepal is in Asia. China is to the north, and India is around the other sides. The capital is Kathmandu, a busy city in a large valley.","zh":"尼泊尔位于亚洲。中国在北边，印度在其他几侧。首都是加德满都，这是一座位于大山谷中的繁忙城市。","imagePages":["Nepal","Kathmandu Valley"],"caption":"Nepal and the Kathmandu Valley"},{"heading":"High Mountains","headingZh":"高山","en":"Nepal has many high mountains. Mount Everest, the highest mountain on Earth, is on its northern border. Many visitors come to see the Himalayas and enjoy the mountain landscape.","zh":"尼泊尔有许多高山。世界最高峰珠穆朗玛峰位于它的北部边境。许多游客来到这里欣赏喜马拉雅山和高山风景。","imagePages":["Mount Everest","Himalayas"],"caption":"Mount Everest and the Himalayas"},{"heading":"Temples and Religion","headingZh":"寺庙与宗教","en":"Nepal has many temples and old religious places. Hinduism and Buddhism are both important. Lumbini, in southern Nepal, is known as the birthplace of the Buddha.","zh":"尼泊尔有许多寺庙和古老的宗教场所。印度教和佛教都很重要。位于尼泊尔南部的蓝毗尼被认为是佛陀的出生地。","imagePages":["Lumbini","Swayambhunath"],"caption":"Religious heritage in Nepal"}]}]},{"slug":"kazakhstan","name":"Kazakhstan","region":"Asia","flag":"kz","mapId":"398","readOrder":2,"summary":"Wide grasslands, mountains, horse culture, and modern cities meet in Central Asia.","summaryZh":"广阔草原、高山、马文化与现代城市在中亚交会。","facts":{"Capital":"Astana","Languages":"Kazakh and Russian","Landscape":"Steppe, lakes, mountains","Tradition":"Horse culture"},"articles":[{"id":"1","title":"Kazakhstan – A Land of Grasslands and Mountains","titleZh":"哈萨克斯坦——草原与高山之国","level":"A2","summary":"Central Asian geography, horse traditions, and the contrast between nature and modern cities.","summaryZh":"认识哈萨克斯坦的中亚地理、马文化，以及自然与现代城市的对比。","sections":[{"heading":"Grasslands and Mountains","headingZh":"草原与高山","en":"Kazakhstan is in Central Asia. It has huge grasslands, lakes, and high mountains in the southeast. The capital is Astana.","zh":"哈萨克斯坦位于中亚。这里有广阔的草原、湖泊，东南部还有高山。首都是阿斯塔纳。","imagePages":["Kazakhstan","Kazakh Steppe"],"caption":"The open steppe of Kazakhstan"},{"heading":"Horses and Nomadic Culture","headingZh":"马与游牧文化","en":"Horses have been important here for a very long time. In the past, many families moved across the grasslands with their animals. Horse riding and nomadic traditions are still strong cultural symbols today.","zh":"马在这里已经重要了很长时间。过去，许多家庭会带着牲畜在草原上移动。今天，骑马和游牧传统仍然是重要的文化象征。","imagePages":["Kazakh horse","Yurt"],"caption":"Horse and nomadic traditions"},{"heading":"Modern Cities","headingZh":"现代城市","en":"Astana and Almaty have modern buildings, universities, cafés, and busy roads. This creates a clear contrast with the wide open land outside the cities.","zh":"阿斯塔纳和阿拉木图有现代建筑、大学、咖啡馆和繁忙道路。这与城市外广阔开阔的土地形成明显对比。","imagePages":["Astana","Almaty"],"caption":"Modern urban life in Kazakhstan"}]}]},{"slug":"kyrgyzstan","name":"Kyrgyzstan","region":"Asia","flag":"kg","mapId":"417","readOrder":3,"summary":"A mountain country where yurts, summer pastures, and horse culture remain easy to see.","summaryZh":"这是一个高山国家，蒙古包、夏季牧场与马文化至今仍很常见。","facts":{"Capital":"Bishkek","Languages":"Kyrgyz and Russian","Landscape":"Tien Shan mountains","Tradition":"Yurts and summer pastures"},"articles":[{"id":"1","title":"Kyrgyzstan – Mountains, Yurts, and Summer Pastures","titleZh":"吉尔吉斯斯坦——高山、蒙古包和夏季牧场","level":"A2","summary":"A mountain-centered introduction to yurts, pastoral life, and modern Kyrgyzstan.","summaryZh":"从高山、蒙古包、牧业生活与现代城市认识吉尔吉斯斯坦。","sections":[{"heading":"A Mountain Country","headingZh":"高山国家","en":"Kyrgyzstan is in Central Asia, and mountains cover most of the country. The Tien Shan range shapes roads, villages, weather, and travel.","zh":"吉尔吉斯斯坦位于中亚，大部分国土都是山区。天山山脉影响道路、村庄、天气和交通。","imagePages":["Kyrgyzstan","Tian Shan"],"caption":"The Tien Shan mountains"},{"heading":"Yurts and Summer Pastures","headingZh":"蒙古包与夏季牧场","en":"The yurt is a round portable home connected with nomadic life. In warm months, some families move animals to high summer pastures, where yurts are still used.","zh":"蒙古包是一种与游牧生活有关的圆形可移动住所。在温暖的月份，一些家庭会把牲畜带到高山夏季牧场，那里至今仍会使用蒙古包。","imagePages":["Yurt","Jailoo"],"caption":"Yurts on high summer pastures"},{"heading":"Horses and Modern Life","headingZh":"马文化与现代生活","en":"Horses remain important in traditional games and rural life. At the same time, Bishkek has apartments, universities, cafés, and modern businesses.","zh":"马在传统游戏和乡村生活中仍然很重要。同时，比什凯克也有公寓、大学、咖啡馆和现代企业。","imagePages":["Kok-boru","Bishkek"],"caption":"Traditional horse culture and modern Bishkek"}]}]},{"slug":"uzbekistan","name":"Uzbekistan","region":"Asia","flag":"uz","mapId":"860","readOrder":4,"summary":"Silk Road cities, plov, blue-tiled architecture, crafts, and round bread define this Central Asian stop.","summaryZh":"丝绸之路城市、抓饭、蓝色瓷砖建筑、手工艺和圆饼，是这个中亚国家的重要特色。","facts":{"Capital":"Tashkent","Language":"Uzbek","Heritage":"Silk Road","Food":"Plov and round bread"},"articles":[{"id":"1","title":"Uzbekistan – Silk Road Cities, Plov, and Traditional Crafts","titleZh":"乌兹别克斯坦——丝绸之路城市、抓饭和传统手工艺","level":"A2","summary":"The accepted three-part focus: Silk Road cities, plov for guests, and traditional crafts with round bread.","summaryZh":"以三个重点认识乌兹别克斯坦：丝绸之路城市、招待客人的抓饭，以及传统手工艺和圆饼。","sections":[{"heading":"Silk Road Cities","headingZh":"丝绸之路城市","en":"For centuries, important Silk Road routes crossed Uzbekistan. Old cities became centers of trade and learning, and many buildings were covered with blue tiles, domes, and detailed patterns.","zh":"几个世纪以来，重要的丝绸之路路线经过乌兹别克斯坦。古老城市成为贸易和学习中心，许多建筑覆盖着蓝色瓷砖、圆顶和精细图案。","imagePages":["Registan","Samarkand"],"caption":"Blue-tiled Silk Road architecture"},{"heading":"Plov for Many Guests","headingZh":"为许多客人准备的抓饭","en":"Plov is one of the best-known foods in Uzbekistan. Rice, meat, carrots, and spices are cooked in a large pot, and the dish is often prepared for many guests at weddings or family events.","zh":"抓饭是乌兹别克斯坦最有名的食物之一。米饭、肉、胡萝卜和香料会放在大锅里一起煮，婚礼或家庭活动时常会为许多客人准备。","imagePages":["Plov","Uzbek cuisine"],"caption":"Plov cooked in a large pot"},{"heading":"Crafts and Round Bread","headingZh":"手工艺与圆饼","en":"Traditional crafts include colorful cloth, pottery, wood carving, and metal work. Round bread is also part of daily meals and is treated with respect in many homes.","zh":"传统手工艺包括彩色布料、陶器、木雕和金属工艺。圆饼也是日常饮食的一部分，在许多家庭中会受到尊重。","imagePages":["Suzani","Obi non"],"caption":"Traditional textiles and round bread"}]}]},{"slug":"turkmenistan","name":"Turkmenistan","region":"Asia","flag":"tm","mapId":"795","readOrder":5,"summary":"Desert life, white marble public architecture, carpets, and Silk Road culture are the main themes.","summaryZh":"沙漠生活、白色大理石公共建筑、地毯与丝绸之路文化是这里的主要主题。","facts":{"Language":"Turkmen","Landscape":"Karakum Desert","Craft":"Carpet weaving","History":"Silk Road culture"},"articles":[{"id":"1","title":"Turkmenistan – Desert, White Marble Buildings, and Carpets","titleZh":"土库曼斯坦——沙漠、白色大理石建筑和地毯","level":"A2","summary":"A concrete introduction without relying on capital-name or world-record claims.","summaryZh":"用具体特色认识土库曼斯坦，不依赖首都名称或世界纪录式描述。","sections":[{"heading":"Life in the Karakum Desert","headingZh":"卡拉库姆沙漠中的生活","en":"Much of Turkmenistan is covered by the Karakum Desert. Water is limited, so settlements and farming have depended on oases, rivers, wells, and canals.","zh":"土库曼斯坦大部分地区被卡拉库姆沙漠覆盖。水资源有限，因此聚落和农业长期依靠绿洲、河流、水井和运河。","imagePages":["Karakum Desert","Turkmenistan"],"caption":"The Karakum Desert"},{"heading":"White Marble Architecture","headingZh":"白色大理石建筑","en":"Large white marble buildings and wide public spaces are a noticeable part of modern urban design in the country. Their bright stone surfaces create a very different image from the surrounding dry landscape.","zh":"大型白色大理石建筑和宽阔公共空间，是这个国家现代城市设计中很醒目的部分。明亮的石材表面与周围干燥的景观形成很不同的画面。","imagePages":["Architecture of Turkmenistan","Ashgabat"],"caption":"White marble public architecture"},{"heading":"Carpets and Silk Road Culture","headingZh":"地毯与丝绸之路文化","en":"Turkmen carpets often use deep red colors and repeating geometric patterns. The region was also connected with Silk Road travel, so desert routes carried people, ideas, and goods across Central Asia.","zh":"土库曼地毯常使用深红色和重复的几何图案。这个地区也与丝绸之路旅行相连，沙漠路线曾让人、思想和商品穿越中亚。","imagePages":["Turkmen rug","Silk Road"],"caption":"Turkmen carpets and historic trade routes"}]}]},{"slug":"afghanistan","name":"Afghanistan","region":"Asia","flag":"af","mapId":"004","readOrder":6,"summary":"High mountains, old trade routes, bazaars, and strong regional traditions define this crossroads.","summaryZh":"高山、古老贸易路线、集市与强烈的地区传统共同塑造了这个十字路口。","facts":{"Capital":"Kabul","Languages":"Dari and Pashto","Landscape":"Hindu Kush and valleys","Level note":"A2–B1"},"articles":[{"id":"1","title":"Afghanistan – Mountains, Bazaars, and Old Crossroads","titleZh":"阿富汗——高山、集市和古老十字路口","level":"A2–B1","summary":"A slightly higher-level article about geography, historic movement, and local cultural variety.","summaryZh":"一篇稍高难度的文章，介绍地理、历史上的往来以及地区文化差异。","sections":[{"heading":"Mountains and Valleys","headingZh":"高山与山谷","en":"The Hindu Kush mountains divide many parts of Afghanistan. Because travel between valleys can be difficult, communities developed strong local languages, customs, clothing, and food traditions.","zh":"兴都库什山脉把阿富汗许多地区分隔开来。因为不同山谷之间的交通可能很困难，各地发展出很强的地方语言、习俗、服装和饮食传统。","imagePages":["Hindu Kush","Geography of Afghanistan"],"caption":"The Hindu Kush mountains"},{"heading":"Old Crossroads","headingZh":"古老十字路口","en":"For centuries, routes through this land linked Central Asia, Iran, and the Indian subcontinent. Traders and travelers carried goods and ideas through mountain passes and important towns.","zh":"几个世纪以来，经过这片土地的路线连接中亚、伊朗和印度次大陆。商人和旅行者通过山口和重要城镇带来商品与思想。","imagePages":["Silk Road","Bamyan"],"caption":"Historic routes through Afghanistan"},{"heading":"Bazaars and Hospitality","headingZh":"集市与待客文化","en":"Traditional bazaars sell food, cloth, tools, carpets, and household goods. Tea and hospitality are also important when guests visit a home, and family networks remain central in many communities.","zh":"传统集市出售食物、布料、工具、地毯和家庭用品。客人到家里时，茶和待客文化也很重要，而家庭关系在许多社区中仍然处于核心位置。","imagePages":["Bazaar","Culture of Afghanistan"],"caption":"Bazaar life and hospitality"}]}]},{"slug":"pakistan","name":"Pakistan","region":"Asia","flag":"pk","mapId":"586","readOrder":7,"summary":"The Indus River, ancient urban history, mountain valleys, and strong regional cultures shape Pakistan.","summaryZh":"印度河、古代城市历史、高山山谷和强烈的地区文化共同塑造巴基斯坦。","facts":{"Capital":"Islamabad","Language":"Urdu plus regional languages","River":"Indus","Landscape":"Plains, deserts, high mountains"},"articles":[{"id":"1","title":"Pakistan – The Indus River, Ancient Cities, and Mountain Valleys","titleZh":"巴基斯坦——印度河、古代城市和高山山谷","level":"A2","summary":"A concrete introduction to the river system, old cities, and regional variety.","summaryZh":"从河流系统、古代城市与地区差异认识巴基斯坦。","sections":[{"heading":"The Indus River","headingZh":"印度河","en":"The Indus River runs through a large part of Pakistan. Its water supports farms, towns, and cities, especially across the broad plains of the country.","zh":"印度河流经巴基斯坦很大一部分地区。它的水支持农田、城镇和城市，特别是在这个国家广阔的平原上。","imagePages":["Indus River","Indus Valley"],"caption":"The Indus River"},{"heading":"Ancient Urban History","headingZh":"古代城市历史","en":"Thousands of years ago, the Indus region had planned cities with streets, wells, and drainage systems. These sites show that complex urban life developed here very early.","zh":"几千年前，印度河地区已经有规划整齐的城市，拥有街道、水井和排水系统。这些遗址说明复杂的城市生活很早就在这里发展。","imagePages":["Mohenjo-daro","Indus Valley Civilisation"],"caption":"Ancient Indus cities"},{"heading":"Many Regions and Cultures","headingZh":"多样的地区与文化","en":"Pakistan includes deserts, farming plains, large cities, and very high mountain valleys. Languages, clothing, music, and food change from one region to another, so the country has strong local identities.","zh":"巴基斯坦包含沙漠、农业平原、大城市和非常高的山谷。语言、服装、音乐和食物会因地区而不同，因此这个国家有很强的地方特色。","imagePages":["Karakoram","Culture of Pakistan"],"caption":"High mountain regions and local cultures"}]}]},{"slug":"iran","name":"Iran","region":"Middle East","flag":"ir","mapId":"364","readOrder":8,"summary":"Persian gardens, tiled architecture, bazaars, poetry, and family hospitality are central themes.","summaryZh":"波斯花园、瓷砖建筑、集市、诗歌与家庭待客文化是主要主题。","facts":{"Capital":"Tehran","Language":"Persian","Landscape":"Mountains, plateaus, deserts","Culture":"Persian heritage"},"articles":[{"id":"1","title":"Iran – Persian Gardens, Bazaars, and Tile Architecture","titleZh":"伊朗——波斯花园、集市和瓷砖建筑","level":"A2","summary":"A visual introduction to Persian design, public markets, and hospitality.","summaryZh":"从波斯设计、公共市场与待客文化认识伊朗。","sections":[{"heading":"Persian Gardens","headingZh":"波斯花园","en":"Persian gardens often use straight paths, trees, shade, and flowing water. In a dry climate, the careful design creates a cool and calm space.","zh":"波斯花园常使用笔直小路、树木、阴影和流动的水。在干燥气候中，这种细致设计能创造凉爽而平静的空间。","imagePages":["Persian garden","Fin Garden"],"caption":"A Persian garden"},{"heading":"Tile Architecture","headingZh":"瓷砖建筑","en":"Many historic buildings use blue, turquoise, and yellow tiles with geometric or flower patterns. Domes, courtyards, and calligraphy are also common parts of Persian architecture.","zh":"许多历史建筑使用蓝色、青绿色和黄色瓷砖，并带有几何或花卉图案。圆顶、庭院和书法也是波斯建筑中常见的元素。","imagePages":["Iranian architecture","Shah Mosque (Isfahan)"],"caption":"Persian tile architecture"},{"heading":"Bazaars and Hospitality","headingZh":"集市与待客文化","en":"Traditional bazaars connect shops, workshops, food stalls, and social life. When guests visit a home, tea, fruit, and sweets are common ways to welcome them.","zh":"传统集市把商店、工坊、食物摊位和社交生活连接在一起。客人到家里时，茶、水果和甜点是常见的招待方式。","imagePages":["Grand Bazaar, Tehran","Iranian tea culture"],"caption":"Bazaar and hospitality culture"}]}]},{"slug":"azerbaijan","name":"Azerbaijan","region":"Middle East","flag":"az","mapId":"031","readOrder":9,"summary":"Natural fire, Caspian coastal life, carpets, tea, and the meeting of several cultural regions.","summaryZh":"天然火焰、里海沿岸生活、地毯、茶文化，以及多种文化区域的交会。","facts":{"Capital":"Baku","Language":"Azerbaijani","Coast":"Caspian Sea","Craft":"Carpet weaving"},"articles":[{"id":"1","title":"Azerbaijan – Fire, Carpets, and the Caspian Sea","titleZh":"阿塞拜疆——火焰、地毯和里海","level":"A2","summary":"A country article built around visible, memorable cultural symbols.","summaryZh":"以容易记住、看得见的文化符号认识阿塞拜疆。","sections":[{"heading":"Fire from the Ground","headingZh":"从地下燃烧的火","en":"Natural gas reaches the surface in some places in Azerbaijan and can burn for long periods. Because of this, fire became a strong historical and modern symbol of the country.","zh":"在阿塞拜疆的一些地方，天然气会从地表冒出并长时间燃烧。因此，火焰成为这个国家重要的历史与现代象征。","imagePages":["Yanar Dag","Ateshgah of Baku"],"caption":"Natural fire near Baku"},{"heading":"Carpets and Patterns","headingZh":"地毯与图案","en":"Carpet weaving has a long tradition. Different regions developed their own colors and geometric patterns, and carpets were used both in homes and for special events.","zh":"地毯编织有很长的传统。不同地区发展出自己的颜色和几何图案，地毯既用于家庭，也用于特殊活动。","imagePages":["Azerbaijani rug","Azerbaijan Carpet Museum"],"caption":"Azerbaijani carpet traditions"},{"heading":"The Caspian and Tea","headingZh":"里海与茶文化","en":"Baku stands on the Caspian Sea, so the waterfront is an important part of the city. Tea is also common in social life and is often served to guests with sweets or jam.","zh":"巴库位于里海岸边，因此海滨是城市的重要部分。茶在社交生活中也很常见，招待客人时常会配上甜点或果酱。","imagePages":["Baku Boulevard","Azerbaijani tea culture"],"caption":"Baku and tea culture"}]}]},{"slug":"georgia","name":"Georgia","region":"Middle East","flag":"ge","mapId":"268","readOrder":10,"summary":"Caucasus mountains, stone churches, an ancient wine tradition, and a distinctive alphabet.","summaryZh":"高加索山脉、石造教堂、古老酿酒传统与独特字母，是格鲁吉亚的重要特色。","facts":{"Capital":"Tbilisi","Language":"Georgian","Landscape":"Caucasus mountains","Tradition":"Wine in clay vessels"},"articles":[{"id":"1","title":"Georgia – Mountains, Stone Churches, and Wine","titleZh":"格鲁吉亚——高山、石造教堂和葡萄酒","level":"A2","summary":"A Caucasus article about landscape, religious architecture, wine, and language.","summaryZh":"从高加索地景、宗教建筑、葡萄酒与语言认识格鲁吉亚。","sections":[{"heading":"Caucasus Mountains","headingZh":"高加索山脉","en":"Georgia lies between the Black Sea and the Caucasus Mountains. High valleys and mountain roads create dramatic landscapes and have helped different regions keep strong local traditions.","zh":"格鲁吉亚位于黑海与高加索山脉之间。高山山谷和山路形成壮观景色，也让不同地区保留了强烈的地方传统。","imagePages":["Caucasus Mountains","Geography of Georgia (country)"],"caption":"The Caucasus landscape"},{"heading":"Stone Churches","headingZh":"石造教堂","en":"Old stone churches and monasteries can be seen on hills, in valleys, and inside historic towns. Christianity has been important in Georgian culture for many centuries.","zh":"古老的石造教堂和修道院可以在山丘、山谷和历史城镇中看到。基督教在格鲁吉亚文化中已经重要了许多个世纪。","imagePages":["Georgian Orthodox Church","Jvari Monastery"],"caption":"Georgian stone churches"},{"heading":"Wine and Alphabet","headingZh":"葡萄酒与字母","en":"Georgia has a very old wine-making tradition, including wine made in large clay vessels placed in the ground. Georgian also uses its own alphabet, so written Georgian has a very distinctive appearance.","zh":"格鲁吉亚有非常古老的酿酒传统，其中包括把葡萄酒放在埋入地下的大型陶罐中制作。格鲁吉亚语也使用自己的字母，因此书写形式非常独特。","imagePages":["Georgian wine","Georgian scripts"],"caption":"Wine vessels and Georgian writing"}]}]},{"slug":"greece","name":"Greece","region":"Europe","flag":"gr","mapId":"300","readOrder":11,"summary":"Ancient city culture, islands, Orthodox traditions, olive oil, and sea life shape Greece.","summaryZh":"古代城市文化、岛屿、东正教传统、橄榄油与海洋生活共同塑造希腊。","facts":{"Capital":"Athens","Language":"Greek","Currency":"Euro","Landscape":"Mountains and islands"},"articles":[{"id":"1","title":"Greece – Islands, Ancient Cities, and Everyday Mediterranean Life","titleZh":"希腊——岛屿、古代城市和地中海日常生活","level":"A2","summary":"A balanced introduction to ancient heritage, islands, religion, and food.","summaryZh":"从古代遗产、岛屿、宗教与饮食认识希腊。","sections":[{"heading":"Ancient Cities and Ideas","headingZh":"古代城市与思想","en":"Ancient Greek cities developed important traditions in politics, theater, philosophy, art, and science. Temples and ruins still make this past visible in modern Greece.","zh":"古希腊城市在政治、戏剧、哲学、艺术和科学方面发展出重要传统。今天的希腊仍能通过神庙和遗址看见这段过去。","imagePages":["Acropolis of Athens","Ancient Greece"],"caption":"Ancient Greek architecture"},{"heading":"Islands and the Sea","headingZh":"岛屿与海洋","en":"Greece has thousands of islands and a very long coastline. Small harbors, ferries, fishing boats, white houses, and narrow streets are common sights in many island communities.","zh":"希腊拥有数千个岛屿和很长的海岸线。小港口、渡轮、渔船、白色房屋和狭窄街道，在许多岛屿社区都很常见。","imagePages":["Greek islands","Santorini"],"caption":"Greek island life"},{"heading":"Orthodox Traditions and Food","headingZh":"东正教传统与饮食","en":"Orthodox churches and religious holidays remain important in many communities. Everyday food often uses olive oil, vegetables, bread, cheese, fish, and grilled meat.","zh":"东正教教堂和宗教节日在许多社区中仍然很重要。日常饮食常使用橄榄油、蔬菜、面包、奶酪、鱼和烤肉。","imagePages":["Greek Orthodox Church","Greek cuisine"],"caption":"Religion and Mediterranean food"}]}]},{"slug":"bulgaria","name":"Bulgaria","region":"Europe","flag":"bg","mapId":"100","readOrder":12,"summary":"Damask roses, red-and-white spring threads, and yogurt give Bulgaria several distinctive cultural symbols.","summaryZh":"大马士革玫瑰、红白春季手绳与酸奶，让保加利亚拥有几个很鲜明的文化符号。","facts":{"Capital":"Sofia","Language":"Bulgarian","Region":"Balkans","Distinctive":"Roses, martenitsa, yogurt"},"articles":[{"id":"1","title":"Bulgaria – Roses, Red-and-White Threads, and Yogurt","titleZh":"保加利亚——玫瑰、红白线和酸奶","level":"A2","summary":"The final accepted Bulgaria focus: Rose Valley, spring martenitsa threads, and yogurt culture.","summaryZh":"采用先前确定的三个重点：玫瑰谷、春季红白线与酸奶文化。","sections":[{"heading":"Damask Roses and the Rose Valley","headingZh":"大马士革玫瑰与玫瑰谷","en":"In central Bulgaria, the Rose Valley is known for Damask roses. Their flowers are collected to make rose oil and rose water, and the harvest season is celebrated with local events.","zh":"在保加利亚中部，玫瑰谷以大马士革玫瑰闻名。花朵会被采集来制作玫瑰油和玫瑰水，收获季也会举行当地活动。","imagePages":["Rose Valley, Bulgaria","Rosa × damascena"],"caption":"Damask roses in Bulgaria"},{"heading":"Red-and-White Threads","headingZh":"红白线","en":"At the beginning of March, people often give small red-and-white threads called martenitsa. They are worn for good health and the arrival of spring, and later they may be tied to a tree.","zh":"三月初，人们常会互赠叫做马尔泰尼察的红白小线饰。它们象征健康和春天到来，之后有时会绑在树上。","imagePages":["Martenitsa","Baba Marta"],"caption":"Martenitsa spring threads"},{"heading":"Yogurt","headingZh":"酸奶","en":"Yogurt is common in Bulgarian food and is used in both simple meals and cold soups. It is one of the foods most strongly connected with the country’s everyday cuisine.","zh":"酸奶在保加利亚饮食中很常见，会用于简单餐点和冷汤。它是最能让人联想到这个国家日常饮食的食物之一。","imagePages":["Bulgarian yogurt","Tarator"],"caption":"Bulgarian yogurt and tarator"}]}]},{"slug":"north-macedonia","name":"North Macedonia","region":"Europe","flag":"mk","mapId":"807","readOrder":13,"summary":"An ancient lake, red-pepper traditions, and silver craftwork are memorable features of North Macedonia.","summaryZh":"古老湖泊、红椒传统与银饰工艺，是北马其顿容易记住的特色。","facts":{"Capital":"Skopje","Language":"Macedonian","Landmark":"Lake Ohrid","Craft":"Silver filigree"},"articles":[{"id":"1","title":"North Macedonia – Ancient Lake, Red Peppers, and Silver Crafts","titleZh":"北马其顿——古老湖泊、红椒和银饰工艺","level":"A2","summary":"The previously accepted three-theme country article.","summaryZh":"沿用先前确定的三个主题。","sections":[{"heading":"An Ancient Lake","headingZh":"古老的湖","en":"Lake Ohrid is one of the country’s best-known natural places. It is very old, very deep, and surrounded by mountains, towns, churches, and clear water.","zh":"奥赫里德湖是这个国家最有名的自然景观之一。它非常古老、很深，周围有山脉、城镇、教堂和清澈湖水。","imagePages":["Lake Ohrid","Ohrid"],"caption":"Lake Ohrid"},{"heading":"Red Peppers and Ajvar","headingZh":"红椒与阿伊瓦酱","en":"Red peppers are an important autumn food. Families may roast and peel many peppers to make ajvar, a thick red spread that is eaten with bread and other foods.","zh":"红椒是重要的秋季食物。家庭有时会烤很多红椒并去皮，再做成浓稠的红色阿伊瓦酱，搭配面包和其他食物食用。","imagePages":["Ajvar","Capsicum annuum"],"caption":"Ajvar made from red peppers"},{"heading":"Silver Crafts","headingZh":"银饰工艺","en":"Traditional silver filigree uses very thin metal wires to create detailed jewelry and decorative objects. This type of craft can still be seen in old market areas and souvenir workshops.","zh":"传统银丝工艺使用非常细的金属线制作精细首饰和装饰品。这类工艺至今仍能在旧市场区和纪念品工坊看到。","imagePages":["Filigree","Old Bazaar, Skopje"],"caption":"Fine silver filigree work"}]}]},{"slug":"kosovo","name":"Kosovo","region":"Europe","flag":"xk","mapId":"383","readOrder":14,"summary":"Stone bridges, silver filigree, and layered flija are three concrete ways to remember Kosovo.","summaryZh":"石桥、银丝工艺与层层烤制的弗利亚，是认识科索沃的三个具体记忆点。","facts":{"Capital":"Pristina","Languages":"Albanian and Serbian","Craft":"Silver filigree","Food":"Flija"},"articles":[{"id":"1","title":"Kosovo – Stone Bridges, Silver Crafts, and Flija","titleZh":"科索沃——石桥、银饰工艺和弗利亚","level":"A2","summary":"A cultural article based on the accepted bridge, craft, and food themes.","summaryZh":"以先前确定的石桥、工艺与食物三个主题介绍科索沃。","sections":[{"heading":"Stone Bridges and Old Streets","headingZh":"石桥与老街","en":"Historic towns in Kosovo have old stone bridges, narrow streets, mosques, churches, and market areas. These places show the region’s long connection with Balkan and Ottoman history.","zh":"科索沃的一些历史城镇有古老石桥、狭窄街道、清真寺、教堂和市场区。这些地方展现了当地与巴尔干及奥斯曼历史的长期联系。","imagePages":["Prizren","Stone Bridge, Prizren"],"caption":"Historic Prizren and its stone bridge"},{"heading":"Silver Filigree","headingZh":"银丝工艺","en":"Silver filigree is made by shaping thin silver wires into detailed patterns. Small workshops continue this craft and produce jewelry, boxes, and decorative pieces.","zh":"银丝工艺是把细银线弯成精细图案。小型工坊至今仍延续这种技术，制作首饰、盒子和装饰品。","imagePages":["Filigree","Prizren"],"caption":"Traditional silver filigree"},{"heading":"Flija","headingZh":"弗利亚","en":"Flija is made from many thin layers of batter and cream. The layers are baked slowly, often for a family gathering, so making the dish can take several hours.","zh":"弗利亚由许多薄薄的面糊和奶油层组成。每一层都要慢慢烤，常用于家庭聚会，因此制作可能需要好几个小时。","imagePages":["Flia","Kosovan cuisine"],"caption":"Flija, a layered baked dish"}]}]},{"slug":"montenegro","name":"Montenegro","region":"Europe","flag":"me","mapId":"499","readOrder":15,"summary":"Stone coastal towns, one-string gusle music, and smoked ham form a distinctive Montenegro article.","summaryZh":"石造海岸城镇、单弦古斯莱音乐与烟熏火腿，构成黑山很鲜明的介绍。","facts":{"Capital":"Podgorica","Language":"Montenegrin","Coast":"Adriatic Sea","Tradition":"Gusle and smoked ham"},"articles":[{"id":"1","title":"Montenegro – Stone Towns, One-String Music, and Smoked Ham","titleZh":"黑山——石城、单弦音乐和烟熏火腿","level":"A2","summary":"The previously accepted three-theme Montenegro article.","summaryZh":"沿用先前确定的三个黑山主题。","sections":[{"heading":"Stone Towns by the Sea","headingZh":"海边石城","en":"On the Adriatic coast, old towns use pale stone walls, narrow lanes, small squares, and red roofs. Kotor is surrounded by mountains and a deep bay, giving the town a dramatic setting.","zh":"在亚得里亚海岸，一些老城有浅色石墙、狭窄巷道、小广场和红色屋顶。科托尔被高山和深湾包围，形成很有戏剧感的景色。","imagePages":["Kotor","Bay of Kotor"],"caption":"Kotor and the Bay of Kotor"},{"heading":"One-String Gusle Music","headingZh":"单弦古斯莱音乐","en":"The gusle is a traditional one-string instrument. A singer may play it while telling long stories about history, families, battles, and local heroes.","zh":"古斯莱是一种传统单弦乐器。歌者会一边演奏，一边讲述关于历史、家族、战争和地方英雄的长故事。","imagePages":["Gusle","Serbian epic poetry"],"caption":"The one-string gusle"},{"heading":"Smoked Ham","headingZh":"烟熏火腿","en":"In mountain villages, pork can be salted, smoked, and dried in cool air. This smoked ham is often served in thin slices with cheese and bread.","zh":"在山村里，猪肉会经过盐腌、烟熏，再利用凉爽空气风干。这种烟熏火腿常切成薄片，和奶酪、面包一起吃。","imagePages":["Njeguški pršut","Njeguši"],"caption":"Traditional smoked ham"}]}]},{"slug":"romania","name":"Romania","region":"Europe","flag":"ro","mapId":"642","readOrder":16,"summary":"Latin-language roots, Carpathian village life, and painted Orthodox churches make Romania easy to recognize.","summaryZh":"拉丁语言根源、喀尔巴阡山村生活与彩绘东正教教堂，让罗马尼亚很容易被记住。","facts":{"Capital":"Bucharest","Language":"Romanian","Landscape":"Carpathian Mountains","Distinctive":"Painted churches"},"articles":[{"id":"1","title":"Romania – Latin Roots, Mountain Villages, and Painted Churches","titleZh":"罗马尼亚——拉丁根源、山村和彩绘教堂","level":"A2","summary":"The final accepted Romania framing: language, mountain village life, and painted churches.","summaryZh":"沿用最终确定的罗马尼亚结构：语言、山村生活和彩绘教堂。","sections":[{"heading":"A Latin Language in Eastern Europe","headingZh":"东欧的拉丁语言","en":"Romanian is a Romance language, so many of its roots are connected with Latin. This makes Romania linguistically different from many neighboring countries that mainly use Slavic languages.","zh":"罗马尼亚语是一种罗曼语，因此许多词源与拉丁语有关。这让罗马尼亚在语言上与许多主要使用斯拉夫语言的邻国不同。","imagePages":["Romanian language","Romance languages"],"caption":"Romanian and its Latin roots"},{"heading":"Carpathian Mountain Villages","headingZh":"喀尔巴阡山村","en":"In parts of the Carpathians, traditional village life has included sheep, hay making, milk foods, wooden houses, and hand-made crafts. Mountain landscapes strongly shape local work and seasonal life.","zh":"在喀尔巴阡山的一些地区，传统村庄生活包括养羊、晒干草、制作乳制品、木屋和手工艺。高山地景强烈影响当地工作和季节生活。","imagePages":["Carpathian Mountains","Romanian village"],"caption":"Traditional life in the Carpathians"},{"heading":"Painted Churches","headingZh":"彩绘教堂","en":"In northern Romania, some Orthodox churches have large Bible scenes painted across much of their outside walls. Many are around five hundred years old, and this style is unusual in Europe.","zh":"在罗马尼亚北部，一些东正教教堂的外墙大面积画着圣经故事。许多建筑已有大约五百年历史，这种风格在欧洲很特别。","imagePages":["Painted churches of Moldavia","Voroneț Monastery"],"caption":"Painted Orthodox church walls"}]}]},{"slug":"serbia","name":"Serbia","region":"Europe","flag":"rs","mapId":"688","readOrder":17,"summary":"A family saint day, reversible wool carpets, and circle dance are three distinctive Serbian traditions.","summaryZh":"家庭守护圣人日、双面羊毛地毯与圆圈舞，是塞尔维亚三个很有特色的传统。","facts":{"Capital":"Belgrade","Language":"Serbian","Tradition":"Slava and Kolo","Craft":"Pirot carpets"},"articles":[{"id":"1","title":"Serbia – Family Saint Day, Two-Sided Carpets, and Circle Dance","titleZh":"塞尔维亚——家庭圣人日、双面地毯和圆圈舞","level":"A2","summary":"The final accepted Serbia article, focused on three specific traditions.","summaryZh":"沿用最终确定的塞尔维亚文章，聚焦三个具体传统。","sections":[{"heading":"Slava: A Family Saint Day","headingZh":"斯拉瓦：家庭圣人日","en":"Many Serbian Orthodox families celebrate a special family saint day called Slava. Relatives and friends gather for food, candles, bread, and family traditions that can pass from one generation to the next.","zh":"许多塞尔维亚东正教家庭会庆祝叫做斯拉瓦的家庭守护圣人日。亲友会一起吃饭、点蜡烛、分享面包，并把家庭传统一代一代传下去。","imagePages":["Slava (tradition)","Serbian Orthodox Church"],"caption":"A Serbian Slava celebration"},{"heading":"Two-Sided Pirot Carpets","headingZh":"双面皮罗特地毯","en":"Pirot carpets are hand-woven wool carpets with strong geometric designs. They are made so carefully that both sides can be used, which makes the craft easy to recognize.","zh":"皮罗特地毯是手工编织的羊毛地毯，有鲜明的几何图案。它们制作得很细致，两面都可以使用，因此这种工艺很容易辨认。","imagePages":["Pirot carpet","Pirot"],"caption":"Pirot wool carpet patterns"},{"heading":"Kolo Circle Dance","headingZh":"科洛圆圈舞","en":"Kolo is a traditional group dance. People hold hands or stand shoulder to shoulder and move together in a line or circle while folk music plays.","zh":"科洛是一种传统集体舞。人们牵手或肩并肩站着，随着民间音乐排成一列或围成圆圈一起移动。","imagePages":["Kolo (dance)","Serbian folk dance"],"caption":"Kolo circle dancing"}]}]},{"slug":"bosnia-and-herzegovina","name":"Bosnia and Herzegovina","region":"Europe","flag":"ba","mapId":"070","readOrder":18,"summary":"A famous stone bridge, strong coffee ritual, and medieval tombstones make this Balkan country memorable.","summaryZh":"著名石桥、浓厚咖啡仪式与中世纪墓碑，让这个巴尔干国家很有记忆点。","facts":{"Capital":"Sarajevo","Languages":"Bosnian, Croatian, Serbian","Landmark":"Mostar Old Bridge","Heritage":"Stećci tombstones"},"articles":[{"id":"1","title":"Bosnia and Herzegovina – Stone Bridge, Bosnian Coffee, and Medieval Tombstones","titleZh":"波斯尼亚和黑塞哥维那——石桥、波斯尼亚咖啡和中世纪墓碑","level":"A2","summary":"The final accepted Bosnia and Herzegovina article.","summaryZh":"沿用最终确定的波斯尼亚和黑塞哥维那文章。","sections":[{"heading":"The Stone Bridge of Mostar","headingZh":"莫斯塔尔石桥","en":"Mostar is known for a high stone bridge that crosses the Neretva River. The bridge connects two sides of the old town and has become one of the country’s clearest visual symbols.","zh":"莫斯塔尔以一座跨越内雷特瓦河的高石桥闻名。这座桥连接老城两侧，已经成为这个国家最清楚的视觉象征之一。","imagePages":["Stari Most","Mostar"],"caption":"The Old Bridge in Mostar"},{"heading":"Bosnian Coffee","headingZh":"波斯尼亚咖啡","en":"Bosnian coffee is often prepared in a small metal pot called a džezva and served slowly with small cups. Drinking it can be a social moment for conversation rather than only a quick drink.","zh":"波斯尼亚咖啡常用一种叫杰兹瓦的小金属壶煮制，再用小杯慢慢喝。喝咖啡常是一段聊天和社交时间，而不只是快速喝一杯饮料。","imagePages":["Bosnian coffee","Džezva"],"caption":"Bosnian coffee served in a metal pot"},{"heading":"Medieval Tombstones","headingZh":"中世纪墓碑","en":"Across the countryside are medieval stone tombstones called stećci. Many are carved with shapes such as people, animals, stars, crosses, or simple geometric designs.","zh":"在乡村各地可以看到叫做斯特奇的中世纪石墓碑。许多墓碑刻有人物、动物、星星、十字架或简单几何图案。","imagePages":["Stećak","Radimlja"],"caption":"Medieval stećci tombstones"}]}]},{"slug":"hungary","name":"Hungary","region":"Europe","flag":"hu","mapId":"348","readOrder":19,"summary":"A non-Slavic language, thermal-bath culture, and paprika make Hungary stand out in Central Europe.","summaryZh":"一种不同于周围许多语言的语言、温泉浴文化与红椒粉，让匈牙利在中欧很突出。","facts":{"Capital":"Budapest","Language":"Hungarian","River":"Danube","Distinctive":"Thermal baths and paprika"},"articles":[{"id":"1","title":"Hungary – A Unique Language, Thermal Baths, and Paprika","titleZh":"匈牙利——独特语言、温泉浴和红椒粉","level":"A2","summary":"The previously accepted Hungary article.","summaryZh":"沿用先前确定的匈牙利文章。","sections":[{"heading":"A Unique Language","headingZh":"独特的语言","en":"Hungarian belongs to the Uralic language family and is very different from most neighboring Slavic and Germanic languages. Its grammar and vocabulary give the country a clear linguistic identity.","zh":"匈牙利语属于乌拉尔语系，与周围大多数斯拉夫语和日耳曼语很不同。它的语法和词汇让这个国家拥有很鲜明的语言特色。","imagePages":["Hungarian language","Uralic languages"],"caption":"The Hungarian language"},{"heading":"Thermal Baths","headingZh":"温泉浴文化","en":"Budapest and other parts of Hungary have many natural hot springs. Large public bath buildings are places for warm pools, relaxation, exercise, and social time.","zh":"布达佩斯和匈牙利其他地区有许多天然温泉。大型公共浴场是泡温水、放松、运动和社交的地方。","imagePages":["Széchenyi thermal bath","Thermal bath"],"caption":"Thermal bath culture in Budapest"},{"heading":"Paprika","headingZh":"红椒粉","en":"Paprika is a red spice made from dried peppers. It is used in many Hungarian dishes and can be mild or hot, giving soups and stews a deep red color.","zh":"红椒粉是由干燥红椒制成的红色香料。它用于许多匈牙利料理，可以不辣也可以很辣，并让汤和炖菜呈现深红色。","imagePages":["Paprika","Hungarian cuisine"],"caption":"Hungarian paprika"}]}]},{"slug":"austria","name":"Austria","region":"Europe","flag":"at","mapId":"040","readOrder":20,"summary":"Imperial history, classical music, Alpine landscapes, and Heuriger wine taverns define the Austria article.","summaryZh":"帝国历史、古典音乐、阿尔卑斯地景与霍伊里格葡萄酒小酒馆，是奥地利文章的核心。","facts":{"Capital":"Vienna","Language":"German","Landscape":"Alps and Danube valley","Tradition":"Heuriger wine taverns"},"articles":[{"id":"1","title":"Austria – Old Empire, Classical Music, and Wine Taverns","titleZh":"奥地利——旧帝国、古典音乐和葡萄酒小酒馆","level":"A2","summary":"The previously accepted Austria article.","summaryZh":"沿用先前确定的奥地利文章。","sections":[{"heading":"An Old Imperial Center","headingZh":"旧帝国中心","en":"For centuries, Vienna was an important center of a large European empire. Palaces, government buildings, formal gardens, and grand streets still show this imperial history.","zh":"几个世纪以来，维也纳一直是一个大型欧洲帝国的重要中心。宫殿、政府建筑、正式花园和宽阔街道至今仍能看见这段帝国历史。","imagePages":["Habsburg monarchy","Hofburg"],"caption":"Imperial architecture in Vienna"},{"heading":"Classical Music","headingZh":"古典音乐","en":"Austria has a strong classical-music tradition. Concert halls, opera houses, music schools, and orchestras are still an important part of cultural life, especially in Vienna and Salzburg.","zh":"奥地利有很深的古典音乐传统。音乐厅、歌剧院、音乐学校和乐团至今仍是文化生活的重要部分，特别是在维也纳和萨尔茨堡。","imagePages":["Vienna State Opera","Classical music"],"caption":"Austria’s classical-music tradition"},{"heading":"Heuriger Wine Taverns","headingZh":"霍伊里格葡萄酒小酒馆","en":"Around Vienna and other wine regions, a Heuriger is a traditional place where local new wine is served with simple food. These taverns often have gardens and a relaxed social atmosphere.","zh":"在维也纳周边和其他葡萄酒地区，霍伊里格是一种提供当地新酒和简单食物的传统小酒馆。这些地方常有花园和轻松的社交气氛。","imagePages":["Heuriger","Vienna wine"],"caption":"A traditional Heuriger"}]}]},{"slug":"slovenia","name":"Slovenia","region":"Europe","flag":"si","mapId":"705","readOrder":21,"summary":"Beekeeping, wooden hayracks, and potica rolled cake create a very distinctive Slovenia article.","summaryZh":"养蜂、木制干草架与波提察卷蛋糕，构成斯洛文尼亚很有特色的文章。","facts":{"Capital":"Ljubljana","Language":"Slovene","Landscape":"Alps, forests, karst","Tradition":"Beekeeping"},"articles":[{"id":"1","title":"Slovenia – Beekeeping, Hayracks, and Potica","titleZh":"斯洛文尼亚——养蜂、干草架和传统卷蛋糕","level":"A2","summary":"The final accepted Slovenia article.","summaryZh":"沿用最终确定的斯洛文尼亚文章。","sections":[{"heading":"Beekeeping Culture","headingZh":"养蜂文化","en":"Beekeeping has a long tradition in Slovenia. Painted beehive panels, local honey, and the Carniolan honey bee are strongly connected with rural culture and environmental education.","zh":"养蜂在斯洛文尼亚有很长的传统。彩绘蜂箱板、当地蜂蜜和卡尼鄂拉蜜蜂，都与乡村文化和环境教育紧密相关。","imagePages":["Carniolan honey bee","Beekeeping in Slovenia"],"caption":"Slovenian beekeeping culture"},{"heading":"Wooden Hayracks","headingZh":"木制干草架","en":"Traditional wooden hayracks stand in fields and are used to dry hay or store farm products. Their special shape is one of the most recognizable parts of the Slovenian countryside.","zh":"传统木制干草架立在田野中，用来晒干草或存放农产品。它们特殊的形状，是斯洛文尼亚乡村最容易辨认的景象之一。","imagePages":["Hayrack","Toplar hayrack"],"caption":"Traditional Slovenian hayracks"},{"heading":"Potica","headingZh":"波提察卷蛋糕","en":"Potica is a rolled cake filled with ingredients such as walnuts, poppy seeds, or other sweet fillings. It is often prepared for holidays and family celebrations.","zh":"波提察是一种卷蛋糕，里面可以加入核桃、罂粟籽或其他甜馅。它常在节日和家庭庆祝时制作。","imagePages":["Potica","Slovenian cuisine"],"caption":"Potica rolled cake"}]}]},{"slug":"croatia","name":"Croatia","region":"Europe","flag":"hr","mapId":"191","readOrder":22,"summary":"The necktie, klapa singing, and red-heart licitar cookies are memorable Croatian cultural symbols.","summaryZh":"领带、克拉帕合唱与红心利奇塔尔饼，是很有记忆点的克罗地亚文化符号。","facts":{"Capital":"Zagreb","Language":"Croatian","Coast":"Adriatic Sea","Distinctive":"Necktie, klapa, licitar"},"articles":[{"id":"1","title":"Croatia – Ties, Singing, and Red Heart Cookies","titleZh":"克罗地亚——领带、合唱和红心饼干","level":"A2","summary":"The previously accepted Croatia article.","summaryZh":"沿用先前确定的克罗地亚文章。","sections":[{"heading":"The Necktie Connection","headingZh":"领带的来源联系","en":"The modern necktie is often connected with Croatian soldiers who wore cloth around the neck in seventeenth-century Europe. The style became fashionable in France and later developed into the tie used today.","zh":"现代领带常与十七世纪欧洲的克罗地亚士兵有关，他们会在脖子上系布。这种样式后来在法国流行，并逐渐发展成今天的领带。","imagePages":["Cravat (early)","Necktie"],"caption":"The historical cravat"},{"heading":"Klapa Singing","headingZh":"克拉帕合唱","en":"Klapa is a traditional style of group singing from the Adriatic coast. Several voices sing closely together, often without many instruments, creating a rich and warm sound.","zh":"克拉帕是亚得里亚海岸的传统合唱形式。几个人的声音紧密配合，常常没有太多乐器，形成浓厚而温暖的声音。","imagePages":["Klapa","Dalmatia"],"caption":"Traditional klapa singing"},{"heading":"Red Heart Licitar","headingZh":"红心利奇塔尔","en":"Licitar are brightly decorated honey-dough cookies, often made in a red heart shape. They can be gifts, decorations, or festival souvenirs rather than only everyday food.","zh":"利奇塔尔是一种颜色鲜艳、用蜂蜜面团制作的装饰饼，常做成红色心形。它们可以是礼物、装饰或节庆纪念品，而不只是日常食物。","imagePages":["Licitar","Croatian cuisine"],"caption":"Red heart-shaped licitar"}]}]},{"slug":"ukraine","name":"Ukraine","region":"Europe","flag":"ua","mapId":"804","readOrder":23,"summary":"Black soil, the Dnipro River, embroidered shirts, and wax-decorated spring eggs are key themes.","summaryZh":"黑土地、第聂伯河、刺绣衬衫与蜡染春季彩蛋，是乌克兰的重要主题。","facts":{"Capital":"Kyiv","Language":"Ukrainian","River":"Dnipro","Landscape":"Plains and rich black soil"},"articles":[{"id":"1","title":"Ukraine – Black Soil, the Dnipro River, and Embroidered Traditions","titleZh":"乌克兰——黑土地、第聂伯河和刺绣传统","level":"A2","summary":"The revised article names the major river and keeps the accepted geography and culture points.","summaryZh":"修订版明确写出重要河流名称，并保留先前确定的地理与文化重点。","sections":[{"heading":"Flat Land and Black Soil","headingZh":"平原与黑土地","en":"Much of Ukraine is made of broad plains with rich black soil. This land is well suited to crops such as wheat, corn, and sunflowers, so farming has long been important.","zh":"乌克兰大部分地区是广阔平原，并拥有肥沃的黑土地。这种土地适合种植小麦、玉米和向日葵，因此农业长期很重要。","imagePages":["Chernozem","Agriculture in Ukraine"],"caption":"Ukraine’s rich black soil"},{"heading":"The Dnipro River","headingZh":"第聂伯河","en":"The Dnipro River runs through a large part of Ukraine and passes through the capital, Kyiv. It has been important for transport, settlement, water, and trade for many centuries.","zh":"第聂伯河流经乌克兰很大一部分地区，并经过首都基辅。几个世纪以来，它一直对交通、聚落、水资源和贸易很重要。","imagePages":["Dnipro","Kyiv"],"caption":"The Dnipro River"},{"heading":"Embroidery and Spring Eggs","headingZh":"刺绣与春季彩蛋","en":"Traditional embroidered shirts use colorful geometric or plant patterns. In spring, people also decorate eggs with wax and colored dyes, a craft that can be passed through families for generations.","zh":"传统刺绣衬衫使用彩色几何或植物图案。春天时，人们也会用蜡和彩色染料装饰鸡蛋，这种工艺可以在家庭中代代传承。","imagePages":["Vyshyvanka","Pysanka"],"caption":"Ukrainian embroidery and pysanka eggs"}]}]},{"slug":"moldova","name":"Moldova","region":"Europe","flag":"md","mapId":"498","readOrder":24,"summary":"Vineyards, underground wine cellars, wall carpets, farmland, and two major rivers characterize Moldova.","summaryZh":"葡萄园、地下酒窖、墙上地毯、农田与两条重要河流，是摩尔多瓦的主要特色。","facts":{"Capital":"Chișinău","Language":"Romanian; Russian also used","Rivers":"Dniester and Prut","Landscape":"Low hills and farmland"},"articles":[{"id":"1","title":"Moldova – Vineyards, Underground Cellars, and Wall Carpets","titleZh":"摩尔多瓦——葡萄园、地下酒窖和传统挂毯","level":"A2","summary":"The earlier Moldova article: geography, vineyards and long cellars, and woven wall carpets.","summaryZh":"沿用先前的摩尔多瓦文章：地理、葡萄园与长地下酒窖，以及传统墙上织毯。","sections":[{"heading":"Farmland Between Two Rivers","headingZh":"两条河之间的农田","en":"Moldova is in Eastern Europe between Romania and Ukraine. It has low hills and farmland, and the Dniester and Prut Rivers are important parts of its geography. Grapes, fruit, corn, and wheat are widely grown.","zh":"摩尔多瓦位于东欧，在罗马尼亚和乌克兰之间。这里有低矮丘陵和农田，第聂斯特河与普鲁特河是重要地理元素。葡萄、水果、玉米和小麦都很常见。","imagePages":["Geography of Moldova","Dniester"],"caption":"Moldova’s farmland and rivers"},{"heading":"Vineyards and Underground Cellars","headingZh":"葡萄园与地下酒窖","en":"Grape growing has a long history in Moldova. Some wine cellars extend through long underground tunnels, where bottles can be stored in cool and stable conditions.","zh":"种植葡萄在摩尔多瓦有很长的历史。一些酒窖延伸成很长的地下隧道，酒瓶可以在凉爽而稳定的环境中储存。","imagePages":["Cricova (winery)","Moldovan wine"],"caption":"Underground wine cellars"},{"heading":"Traditional Wall Carpets","headingZh":"传统墙上织毯","en":"Traditional wool carpets may show flowers, trees, birds, or geometric patterns. They can be placed on walls inside homes, adding color and showing craft traditions passed through families.","zh":"传统羊毛地毯可能画有花、树、鸟或几何图案。它们可以挂在家里的墙上，增加色彩，也展现家庭代代传承的手工艺。","imagePages":["Moldovan carpet","Culture of Moldova"],"caption":"Traditional woven wall carpets"}]}]},{"slug":"germany","name":"Germany","region":"Europe","flag":"de","mapId":"276","readOrder":25,"summary":"Four articles cover geography and federal regions, division and reunification, skilled industry, and everyday traditions.","summaryZh":"四篇文章分别介绍地理与联邦州、分裂与统一、技术产业，以及日常传统。","facts":{"Capital":"Berlin","Language":"German","States":"16","River":"Rhine"},"articles":[{"id":"1","title":"Germany – Rivers, Regions, and 16 States","titleZh":"德国——河流、地区和16个州","level":"A2–B1","summary":"Geography, the Rhine, 16 federal states, and strong regional differences.","summaryZh":"介绍德国地理、莱茵河、16个联邦州与明显的地区差异。","sections":[{"heading":"Central Europe and Nine Neighbors","headingZh":"中欧与九个邻国","en":"Germany is in the center of Europe and has nine neighboring countries. The north is flatter and closer to the North Sea and Baltic Sea, while the south rises toward the Alps.","zh":"德国位于欧洲中部，与九个国家接壤。北部地势较平，靠近北海和波罗的海；南部则逐渐升高，接近阿尔卑斯山。","imagePages":["Germany","Geography of Germany"],"caption":"Germany in Central Europe"},{"heading":"The Rhine River","headingZh":"莱茵河","en":"The Rhine River has been important for trade for hundreds of years. Ships carry goods past cities, vineyards, castles, and industrial areas, linking Germany with other parts of Western Europe.","zh":"莱茵河几百年来一直对贸易很重要。船只载着货物经过城市、葡萄园、城堡和工业区，把德国与西欧其他地区连接起来。","imagePages":["Rhine","Rhine Gorge"],"caption":"The Rhine River and its trade route"},{"heading":"Sixteen Federal States","headingZh":"十六个联邦州","en":"Germany is a federal country made up of 16 states. The states have their own governments and are responsible for important areas such as education, police, and parts of cultural policy.","zh":"德国是由16个州组成的联邦国家。各州有自己的政府，并负责教育、警察以及部分文化政策等重要领域。","imagePages":["States of Germany","Federalism in Germany"],"caption":"Germany’s 16 federal states"},{"heading":"Strong Regional Identities","headingZh":"明显的地区特色","en":"Regional traditions can be very different. Architecture, dialects, festivals, food, and landscapes change from the coast to central forests and southern mountain areas.","zh":"德国不同地区的传统可能差异很大。从海岸到中部森林，再到南部山区，建筑、方言、节庆、食物和地景都会改变。","imagePages":["Culture of Germany","Bavaria"],"caption":"Regional culture in Germany"}]},{"id":"2","title":"Germany – Division, the Berlin Wall, and Reunification","titleZh":"德国——分裂、柏林墙与统一","level":"A2–B1","summary":"A four-part history article from the modern federal state to division and reunification.","summaryZh":"用四段认识现代德国形成、战后分裂、柏林墙与重新统一。","sections":[{"heading":"A Modern Federal State","headingZh":"现代联邦国家","en":"Modern Germany became a federal state in 1871. During the following decades, the country changed quickly through industry, cities, war, and political conflict.","zh":"现代德国在1871年成为一个联邦国家。接下来的几十年里，这个国家经历工业化、城市发展、战争与政治冲突，变化很快。","imagePages":["German Empire","History of Germany"],"caption":"Germany after 1871"},{"heading":"Germany Was Divided","headingZh":"德国被分裂","en":"After the Second World War, Germany was divided. Two German states were created in 1949, one in the west and one in the east, with different political and economic systems.","zh":"第二次世界大战后，德国被分裂。1949年出现两个德国国家，一个在西部，一个在东部，拥有不同的政治和经济制度。","imagePages":["History of Germany (1945–1990)","Allied-occupied Germany"],"caption":"Postwar division"},{"heading":"The Berlin Wall","headingZh":"柏林墙","en":"In 1961, a wall was built through Berlin to stop people from leaving East Germany through the city. Families, streets, and neighborhoods were separated for almost three decades.","zh":"1961年，一道墙穿过柏林修建起来，用来阻止人们经由这座城市离开东德。家庭、街道和社区被分隔了将近三十年。","imagePages":["Berlin Wall","Checkpoint Charlie"],"caption":"The Berlin Wall"},{"heading":"Reunification","headingZh":"重新统一","en":"The Berlin Wall opened in 1989 after large political changes and public pressure. In 1990, East and West Germany were officially reunited as one country.","zh":"在重大政治变化和公众压力之后，柏林墙于1989年开放。1990年，东德和西德正式重新统一为一个国家。","imagePages":["German reunification","Fall of the Berlin Wall"],"caption":"German reunification"}]},{"id":"3","title":"Germany – Industry, Skilled Work, and Learning on the Job","titleZh":"德国——工业、技术工作和在职学习","level":"A2–B1","summary":"Machines, cars, medium-sized firms, and vocational education explain an important part of modern Germany.","summaryZh":"机器、汽车、中型企业与职业教育，是理解现代德国的重要部分。","sections":[{"heading":"Machines, Cars, and Equipment","headingZh":"机器、汽车与设备","en":"Germany has a long history of making machines, cars, tools, chemicals, and factory equipment. Manufacturing is spread across many regions rather than being limited to one city.","zh":"德国有很长的机器、汽车、工具、化学品和工厂设备制造历史。制造业分布在许多地区，而不是只集中在一座城市。","imagePages":["Economy of Germany","Automotive industry in Germany"],"caption":"German manufacturing"},{"heading":"Skilled Work","headingZh":"技术型工作","en":"Many German companies depend on skilled workers who understand machines, metal, electronics, design, or production systems. Precision and reliable technical training are important in these jobs.","zh":"许多德国公司依靠熟悉机器、金属、电子、设计或生产系统的技术工人。精确度和可靠的技术训练在这些工作中很重要。","imagePages":["German engineering","Machine industry"],"caption":"Skilled technical work"},{"heading":"Learning at School and Work","headingZh":"在学校与工作中学习","en":"Germany also has a well-known vocational training system. Many young people learn part of the week in a school and the other part inside a company, combining theory with real work.","zh":"德国也有很有名的职业培训制度。许多年轻人一周部分时间在学校学习，另一部分时间在公司工作，把理论和真实工作结合起来。","imagePages":["Dual education system","Vocational education"],"caption":"The dual vocational system"},{"heading":"Medium-Sized Companies","headingZh":"中型企业","en":"Many specialized medium-sized companies make parts or equipment that are sold around the world. These firms are often located outside the largest cities and can remain closely connected with one region.","zh":"许多专业化中型企业生产销往世界各地的零件或设备。这些公司常位于最大城市之外，并与所在地区保持紧密联系。","imagePages":["Mittelstand","Industry in Germany"],"caption":"Germany’s specialized medium-sized firms"}]},{"id":"4","title":"Germany – Bread, Christmas Markets, Sunday, and Clubs","titleZh":"德国——面包、圣诞市场、星期日和社团","level":"A1","summary":"An easier A1 article about four everyday cultural habits.","summaryZh":"一篇较简单的A1文章，介绍四个日常文化习惯。","sections":[{"heading":"Bread","headingZh":"面包","en":"Germany has many kinds of bread. People buy bread and small rolls from bakeries for breakfast or simple meals.","zh":"德国有很多种面包。人们会从面包店买面包和小餐包，作为早餐或简单餐点。","imagePages":["German bread","Bakery"],"caption":"German bread and bakery culture"},{"heading":"Christmas Markets","headingZh":"圣诞市场","en":"In winter, many towns have Christmas markets. People walk between small stalls, drink warm drinks, eat snacks, and buy gifts.","zh":"冬天时，许多城镇都有圣诞市场。人们会在小摊之间散步、喝热饮、吃点心和买礼物。","imagePages":["Christmas market","Nuremberg Christkindlesmarkt"],"caption":"A German Christmas market"},{"heading":"Sunday","headingZh":"星期日","en":"Sunday is often quieter than other days. Many shops close, and people may visit family, go for a walk, or rest at home.","zh":"星期日通常比其他日子安静。许多商店会关门，人们可能去看家人、散步或在家休息。","imagePages":["Shopping hours","Sunday shopping","Ladenschlussgesetz"],"caption":"A quieter Sunday rhythm"},{"heading":"Clubs","headingZh":"社团","en":"Many people join local clubs for sports, music, hobbies, or community activities. Clubs are a common way to meet people who share the same interest.","zh":"许多人会参加当地的运动、音乐、兴趣或社区社团。社团是认识有相同兴趣的人很常见的方式。","imagePages":["Voluntary association","Sport in Germany"],"caption":"Local clubs and community life"}]}]},{"slug":"switzerland","name":"Switzerland","region":"Europe","flag":"ch","mapId":"756","readOrder":26,"summary":"Four articles cover Alpine geography and languages, neutrality and voting, rail and skilled work, and everyday mountain-food traditions.","summaryZh":"四篇文章介绍阿尔卑斯地理与语言、中立与投票、铁路和技术工作，以及山地饮食传统。","facts":{"Capital":"Bern","Languages":"German, French, Italian, Romansh","Cantons":"26","Landscape":"Alps, plateau, Jura"},"articles":[{"id":"1","title":"Switzerland – Alps, Four Languages, and 26 Cantons","titleZh":"瑞士——阿尔卑斯山、四种语言和26个州","level":"A2–B1","summary":"Geography, national languages, cantons, and mountain transport.","summaryZh":"介绍地理、国家语言、州以及山地交通。","sections":[{"heading":"Alps, Plateau, and Jura","headingZh":"阿尔卑斯山、中部高原与汝拉山","en":"Switzerland has three main landscape areas: the Alps, the central plateau, and the Jura Mountains. Most large cities and much of the population are on the central plateau.","zh":"瑞士有三个主要地形区：阿尔卑斯山、中部高原和汝拉山。大多数大城市和许多人口都位于中部高原。","imagePages":["Geography of Switzerland","Swiss Alps"],"caption":"Switzerland’s major landscape regions"},{"heading":"Four National Languages","headingZh":"四种国家语言","en":"Switzerland has four national languages: German, French, Italian, and Romansh. Different parts of the country mainly use different languages in schools, media, and daily life.","zh":"瑞士有四种国家语言：德语、法语、意大利语和罗曼什语。不同地区在学校、媒体和日常生活中主要使用不同语言。","imagePages":["Languages of Switzerland","Linguistic geography of Switzerland"],"caption":"Switzerland’s language regions"},{"heading":"Twenty-Six Cantons","headingZh":"二十六个州","en":"The country is made up of 26 cantons. Cantons have strong local power and make many decisions about education, police, taxes, and public services.","zh":"瑞士由26个州组成。各州拥有很强的地方权力，并在教育、警察、税收和公共服务等方面作出许多决定。","imagePages":["Cantons of Switzerland","Federalism in Switzerland"],"caption":"Switzerland’s 26 cantons"},{"heading":"Mountain Transport and Trade","headingZh":"山地交通与贸易","en":"Mountain geography makes transport difficult, so Switzerland has built many tunnels, bridges, railways, and mountain roads. These links connect language regions and also support trade across the Alps.","zh":"高山地形让交通更困难，因此瑞士修建了许多隧道、桥梁、铁路和山路。这些交通线连接不同语言地区，也支持穿越阿尔卑斯山的贸易。","imagePages":["Transport in Switzerland","Gotthard railway"],"caption":"Transport across the Alps"}]},{"id":"2","title":"Switzerland – Neutrality, Voting, and Local Power","titleZh":"瑞士——中立、投票与地方权力","level":"A2–B1","summary":"The 1848 federal state, 1815 neutrality, direct democracy, and seven-member government.","summaryZh":"介绍1848年联邦国家、1815年中立、直接民主与七人政府。","sections":[{"heading":"The Federal State of 1848","headingZh":"1848年的联邦国家","en":"Modern Switzerland became a federal state in 1848. The new system joined the cantons under a national constitution while still leaving them significant local power.","zh":"现代瑞士在1848年成为联邦国家。新的制度用国家宪法把各州连接起来，同时仍保留很大的地方权力。","imagePages":["Federal Constitution of the Swiss Confederation","History of Switzerland since 1848"],"caption":"The Swiss federal system"},{"heading":"Neutrality","headingZh":"中立政策","en":"Swiss neutrality was internationally recognized in 1815. It means Switzerland normally avoids taking part in wars between other states, although the country still has armed forces and takes part in international diplomacy.","zh":"瑞士的中立地位在1815年获得国际承认。这意味着瑞士通常避免参加其他国家之间的战争，但这个国家仍然拥有军队，也参与国际外交。","imagePages":["Swiss neutrality","Congress of Vienna"],"caption":"Swiss neutrality"},{"heading":"Direct Democracy","headingZh":"直接民主","en":"Swiss citizens vote often on national, cantonal, and local questions. Referendums and popular initiatives give voters a direct role in changing laws or proposing constitutional ideas.","zh":"瑞士公民经常对国家、州和地方问题进行投票。公投和公民倡议让选民可以直接参与修改法律或提出宪法建议。","imagePages":["Voting in Switzerland","Direct democracy"],"caption":"Voting in Switzerland"},{"heading":"A Seven-Member Government","headingZh":"七人政府","en":"The national executive is the Federal Council, which has seven members. Instead of one powerful president leading the government, the members make many decisions together.","zh":"国家行政机构是联邦委员会，共有七名成员。政府并不是由一位权力很大的总统领导，而是由这些成员共同作出许多决定。","imagePages":["Federal Council (Switzerland)","Swiss Federal Council"],"caption":"Switzerland’s seven-member Federal Council"}]},{"id":"3","title":"Switzerland – Railways, Tunnels, Watches, and Skilled Work","titleZh":"瑞士——铁路、隧道、手表和技术工作","level":"A2–B1","summary":"The Gotthard Base Tunnel, rail freight, watchmaking, and vocational training.","summaryZh":"介绍圣哥达基线隧道、铁路货运、制表业与职业培训。","sections":[{"heading":"A 57-Kilometer Rail Tunnel","headingZh":"57公里铁路隧道","en":"The Gotthard Base Tunnel opened in 2016 and is about 57 kilometers long. It runs deep under the Alps and allows trains to cross the mountain region on a much flatter route.","zh":"圣哥达基线隧道在2016年开通，全长约57公里。它深入阿尔卑斯山下方，让火车可以沿更平缓的路线穿越山区。","imagePages":["Gotthard Base Tunnel","Gotthard railway"],"caption":"The Gotthard Base Tunnel"},{"heading":"Railways and Freight","headingZh":"铁路与货运","en":"Switzerland has a dense rail network that connects cities, small towns, and mountain areas. Freight trains also move goods through the Alps between northern and southern Europe.","zh":"瑞士拥有密集的铁路网络，连接城市、小镇和山区。货运列车也会穿越阿尔卑斯山，在欧洲南北之间运输商品。","imagePages":["Swiss Federal Railways","Rail transport in Switzerland"],"caption":"Swiss railway network"},{"heading":"Watchmaking","headingZh":"制表业","en":"Swiss watchmaking developed strong traditions in precision, design, and small mechanical parts. Many watch companies and skilled workshops are concentrated in western parts of the country.","zh":"瑞士制表业在精密度、设计和小型机械零件方面发展出深厚传统。许多手表公司和技术工坊集中在国家西部地区。","imagePages":["Watchmaking in Switzerland","Swiss watch"],"caption":"Swiss watchmaking"},{"heading":"Learning a Skilled Job","headingZh":"学习技术职业","en":"Like Germany, Switzerland has a strong vocational system. Many young people divide their time between school lessons and practical training inside a company.","zh":"和德国一样，瑞士拥有很强的职业教育制度。许多年轻人会把时间分配在学校课程和公司里的实际训练之间。","imagePages":["Education in Switzerland","Vocational education"],"caption":"Vocational learning in Switzerland"}]},{"id":"4","title":"Switzerland – Cheese, Chocolate, Mountain Farms, and Cow Bells","titleZh":"瑞士——奶酪、巧克力、山地农场和牛铃","level":"A1","summary":"An easier article about four familiar parts of Swiss daily and mountain culture.","summaryZh":"一篇较简单的文章，介绍四个熟悉的瑞士日常与山地文化特色。","sections":[{"heading":"Cheese","headingZh":"奶酪","en":"Cheese is common in Swiss food. Fondue is made by melting cheese in a pot and sharing it with bread.","zh":"奶酪在瑞士饮食中很常见。奶酪火锅是把奶酪放在锅里融化，再和大家一起用面包蘸着吃。","imagePages":["Fondue","Swiss cheese"],"caption":"Swiss fondue"},{"heading":"Chocolate","headingZh":"巧克力","en":"Switzerland is also known for chocolate. Shops sell many kinds, from simple milk chocolate to handmade chocolate with nuts or fruit.","zh":"瑞士也以巧克力闻名。商店会卖很多种巧克力，从简单的牛奶巧克力到加入坚果或水果的手工巧克力。","imagePages":["Swiss chocolate","Chocolate"],"caption":"Swiss chocolate"},{"heading":"Mountain Farms","headingZh":"山地农场","en":"In summer, some cows are moved to high Alpine grasslands. Farmers use the fresh grass and milk to make products such as cheese.","zh":"夏天时，一些牛会被带到高海拔的阿尔卑斯草地。农民利用新鲜牧草和牛奶制作奶酪等产品。","imagePages":["Alpine transhumance","Alp (pasture)"],"caption":"Summer Alpine grazing"},{"heading":"Cow Bells","headingZh":"牛铃","en":"Cows in mountain areas often wear bells. The sound helps farmers know where the animals are, and cow bells have also become a strong Swiss cultural symbol.","zh":"山区的牛常会戴牛铃。铃声可以帮助农民知道牛的位置，牛铃也已经成为很强烈的瑞士文化象征。","imagePages":["Cowbell","Alpine transhumance"],"caption":"Cow bells in the Alps"}]}]},{"slug":"france","name":"France","region":"Europe","flag":"fr","mapId":"250","readOrder":27,"summary":"Four articles cover geography and rivers, revolution and republic, art and café culture, and simple food traditions.","summaryZh":"四篇文章介绍地理与河流、革命与共和国、艺术与咖啡馆文化，以及简单饮食传统。","facts":{"Capital":"Paris","Language":"French","Currency":"Euro","Major rivers":"Seine, Loire, Rhône, Garonne"},"articles":[{"id":"1","title":"France – Two Seas, Great Rivers, and Different Regions","titleZh":"法国——两片海、大河与不同地区","level":"A2–B1","summary":"Geography, major rivers, farming products, and regional diversity including overseas France.","summaryZh":"介绍地理、主要河流、农业产品，以及包含海外地区在内的地区多样性。","sections":[{"heading":"Western Europe and Two Seas","headingZh":"西欧与两片海","en":"France is in Western Europe. Its mainland reaches the Atlantic Ocean and the Mediterranean Sea, so coastal landscapes and climates are very different from north to south.","zh":"法国位于西欧。法国本土同时面向大西洋和地中海，因此从北到南，海岸景观与气候差异很大。","imagePages":["Geography of France","Metropolitan France"],"caption":"France between the Atlantic and Mediterranean"},{"heading":"Great Rivers","headingZh":"重要河流","en":"Several major rivers cross France. The Seine passes through Paris, the Loire flows through a long valley with farms and castles, and the Rhône carries water south toward the Mediterranean.","zh":"法国有几条重要河流。塞纳河经过巴黎，卢瓦尔河流经一条拥有农田和城堡的长河谷，罗讷河则向南流入地中海。","imagePages":["Seine","Loire","Rhône"],"caption":"Major rivers of France"},{"heading":"Farming and Regional Products","headingZh":"农业与地区产品","en":"Different regions are known for different products. Wheat, grapes, dairy farming, fruit, seafood, and many kinds of cheese connect food with local climate and geography.","zh":"不同地区以不同产品闻名。小麦、葡萄、乳业、水果、海鲜和多种奶酪，让饮食与当地气候和地理紧密相连。","imagePages":["Agriculture in France","French wine"],"caption":"Regional farming in France"},{"heading":"More Than European Mainland","headingZh":"不只有欧洲本土","en":"France also has overseas regions and territories in the Caribbean, South America, the Indian Ocean, and the Pacific. This makes French geography and culture more diverse than a map of Europe alone suggests.","zh":"法国在加勒比海、南美洲、印度洋和太平洋也有海外地区与领地。因此，法国的地理和文化比只看欧洲地图时更为多样。","imagePages":["Overseas France","Regions of France"],"caption":"Overseas France and regional diversity"}]},{"id":"2","title":"France – Kings, Revolution, and the Republic","titleZh":"法国——国王、革命与共和国","level":"A2–B1","summary":"Monarchy, the 1789 Revolution, republican government, national values, and secular public institutions.","summaryZh":"介绍君主制、1789年革命、共和政府、国家价值与世俗公共制度。","sections":[{"heading":"Kings and Monarchy","headingZh":"国王与君主制","en":"For many centuries, France was ruled by kings. Royal power, taxes, wars, and social differences shaped the country before the late eighteenth century.","zh":"几个世纪以来，法国由国王统治。在十八世纪末以前，王权、税收、战争和社会差异深刻影响这个国家。","imagePages":["Kingdom of France","Palace of Versailles"],"caption":"France under the monarchy"},{"heading":"The Revolution of 1789","headingZh":"1789年革命","en":"In 1789, the French Revolution began during a serious political and financial crisis. Old privileges were challenged, and new ideas about citizenship and rights changed France and influenced other countries.","zh":"1789年，法国在严重的政治与财政危机中爆发革命。旧特权受到挑战，而关于公民与权利的新思想改变了法国，也影响了其他国家。","imagePages":["French Revolution","Storming of the Bastille"],"caption":"The French Revolution"},{"heading":"The Republic","headingZh":"共和国","en":"France today is a republic with an elected president and parliament. The phrase “Liberty, Equality, Fraternity” is used as a national motto and reflects ideas that became important after the Revolution.","zh":"今天的法国是共和国，拥有民选总统和议会。“自由、平等、博爱”是国家格言，反映了革命后变得重要的一些理念。","imagePages":["French Fifth Republic","Liberté, égalité, fraternité"],"caption":"France as a republic"},{"heading":"State and Religion","headingZh":"国家与宗教","en":"French public institutions follow a strong idea of secularism. The state and religious organizations are separate, and public schools emphasize common civic rules rather than one religion.","zh":"法国公共制度强调世俗原则。国家与宗教组织分开，公立学校强调共同的公民规则，而不是某一种宗教。","imagePages":["Secularism in France","Laïcité"],"caption":"French secularism"}]},{"id":"3","title":"France – Art, Fashion, Food, and Café Culture","titleZh":"法国——艺术、时尚、食物和咖啡馆文化","level":"A2–B1","summary":"Museums and art schools, fashion, regional foods, and cafés as social spaces.","summaryZh":"介绍博物馆与艺术教育、时尚、地区食物以及作为社交空间的咖啡馆。","sections":[{"heading":"Art and Museums","headingZh":"艺术与博物馆","en":"France has a long connection with painting, sculpture, architecture, and design. Large museums and art schools collect older works while also supporting new artistic ideas.","zh":"法国与绘画、雕塑、建筑和设计有很长的联系。大型博物馆和艺术学校收藏旧作品，也支持新的艺术思想。","imagePages":["Louvre","Art in France"],"caption":"Museums and art in France"},{"heading":"Fashion","headingZh":"时尚","en":"Paris became an important center for fashion, clothing design, and luxury goods. Fashion houses, workshops, and seasonal shows connect creative design with international business.","zh":"巴黎成为时尚、服装设计和奢侈品的重要中心。时装品牌、工坊和季节性时装秀把创意设计与国际商业连接起来。","imagePages":["Paris Fashion Week","French fashion"],"caption":"Fashion in Paris"},{"heading":"Regional Food","headingZh":"地区饮食","en":"French food changes greatly by region. Coastal areas use seafood, farming areas produce cheese and dairy foods, and wine regions connect local dishes with different grapes and landscapes.","zh":"法国饮食会因地区而有很大差异。沿海地区使用海鲜，农业地区生产奶酪和乳制品，而葡萄酒产区则把当地菜肴与不同葡萄和地景连接起来。","imagePages":["French cuisine","Cuisine of Provence"],"caption":"Regional food in France"},{"heading":"Café Culture","headingZh":"咖啡馆文化","en":"Cafés are common places to sit, talk, read, work, or watch city life. A café table can be a simple social space rather than only a place for a quick drink.","zh":"咖啡馆是常见的坐着聊天、阅读、工作或观察城市生活的地方。咖啡馆的一张桌子可以是简单的社交空间，而不只是快速喝饮料的地方。","imagePages":["Café culture","Café de Flore"],"caption":"French café culture"}]},{"id":"4","title":"France – Bread, Markets, Cheese, and Long Meals","titleZh":"法国——面包、市场、奶酪和长时间用餐","level":"A1","summary":"An easier article about familiar everyday food habits.","summaryZh":"一篇较简单的文章，介绍法国常见的日常饮食习惯。","sections":[{"heading":"Bread","headingZh":"面包","en":"Bread is part of many meals in France. People often buy a fresh baguette from a bakery near their home.","zh":"面包是法国许多餐点的一部分。人们常从家附近的面包店买新鲜法棍。","imagePages":["Baguette","Boulangerie"],"caption":"A French baguette"},{"heading":"Outdoor Markets","headingZh":"户外市场","en":"Many towns have outdoor markets. People can buy fruit, vegetables, cheese, bread, meat, flowers, and other local products.","zh":"许多城镇都有户外市场。人们可以买水果、蔬菜、奶酪、面包、肉、花和其他当地产品。","imagePages":["Market (place)","French market"],"caption":"An outdoor market in France"},{"heading":"Cheese","headingZh":"奶酪","en":"France has many kinds of cheese. Different regions make cheese from cow, goat, or sheep milk, and people may eat it after the main part of a meal.","zh":"法国有很多种奶酪。不同地区会用牛奶、羊奶或山羊奶制作奶酪，人们可能在主餐之后吃。","imagePages":["French cheese","Cheese"],"caption":"French regional cheeses"},{"heading":"Long Meals","headingZh":"长时间用餐","en":"A family meal can last a long time, especially on weekends or special days. People eat several parts of the meal and spend time talking together.","zh":"家庭用餐有时会持续很久，特别是在周末或特殊日子。人们会吃几个不同部分的餐点，并花时间一起聊天。","imagePages":["French cuisine","Meal"],"caption":"A long shared meal"}]}]}];
